  "headline": "Lactulose is not on FDA's shortage list; Corvale General has 23.4 days on hand and Corvale Lakeside has 19.1 days on hand; top alternate is APOZEAL PHARMACEUTICALS INC.",
  "headline_cites": ["D3", "D1", "D2", "D4"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include lactulose as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale General holds 222 eachs of lactulose 10 g/15 mL 30 mL with 9.5 used per day, giving 23.4 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale Lakeside holds 35 eachs of the same presentation with 1.8 used per day, giving 19.1 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The ranked alternate manufacturer is APOZEAL PHARMACEUTICALS INC., which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "The current label for the product we stock names Xttrium Laboratories, Inc. (FEI 3008436464) as the registered manufacturing plant.",
      "cites": ["E16"]
    },
    {
      "text": "FDA inspected that plant on 2025-06-18 and classified it OAI, with the classification known on 2025-09-16.",
      "cites": ["E13"]
    },
    {
      "text": "The most recent inspection ended 2026-06-16 and was classified VAI, known on 2026-08-24.",
      "cites": ["E14"]
    }
  ]
}
